targets.rawQueryText:
SELECT
  metric,
  COUNT(value) AS samples,
  ROUND(AVG(value), 2) AS avg_value,
  ROUND(MIN(value), 2) AS min_value,
  ROUND(MAX(value), 2) AS max_value
FROM (
  SELECT 'server.dictation_finalize.session_ms' AS metric, json_extract(fields_json, '$.session_ms') AS value FROM events WHERE name = 'server.dictation_finalize' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_finalize.audio_duration_ms' AS metric, json_extract(fields_json, '$.audio_duration_ms') AS value FROM events WHERE name = 'server.dictation_finalize' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_finalize.result_updates' AS metric, json_extract(fields_json, '$.result_updates') AS value FROM events WHERE name = 'server.dictation_finalize' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_finalize.stt_ms' AS metric, json_extract(fields_json, '$.stt_ms') AS value FROM events WHERE name = 'server.dictation_finalize' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_finalize.stt_audio_ratio' AS metric, json_extract(fields_json, '$.stt_audio_ratio') AS value FROM events WHERE name = 'server.dictation_finalize' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_finalize.finalize_ms' AS metric, json_extract(fields_json, '$.finalize_ms') AS value FROM events WHERE name = 'server.dictation_finalize' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_first_audio.duration_ms' AS metric, json_extract(fields_json, '$.duration_ms') AS value FROM events WHERE name = 'server.dictation_first_audio' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_first_result.duration_ms' AS metric, json_extract(fields_json, '$.duration_ms') AS value FROM events WHERE name = 'server.dictation_first_result' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_first_result.audio_ms' AS metric, json_extract(fields_json, '$.audio_ms') AS value FROM events WHERE name = 'server.dictation_first_result' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_finalize.errors' AS metric, 1 AS value FROM events WHERE name = 'server.dictation_finalize' AND json_extract(tags_json, '$.status') = 'error' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
  UNION ALL
  SELECT 'server.dictation_stream_error' AS metric, 1 AS value FROM events WHERE name = 'server.dictation_stream_error' AND ts_ms >= ${__from} AND ts_ms <= ${__to}
)
GROUP BY metric
HAVING samples > 0
ORDER BY samples DESC
